mapper.select:
SELECT cap.product_number, CAP.product_name, CAP.product_short_name, CAP.business_type, case when PCD.PLAN_CASH_PRINCIPAL > 0 and PCD.PLAN_CASH_INTEREST > 0 then '本息' when PCD.PLAN_CASH_PRINCIPAL > 0 and PCD.PLAN_CASH_INTEREST <= 0 then '本金' when PCD.PLAN_CASH_PRINCIPAL <= 0 and PCD.PLAN_CASH_INTEREST > 0 then '利息' end as cf_item_n, nvl( PCD.PLAN_CASH_PRINCIPAL, 0 ) + nvl( PCD.PLAN_CASH_INTEREST, 0 ) AS PLAN_CASH_AMOUNT, pcfd.cash_amount_sum, pcfd.cash_interest_sum, pcfd.cash_principal_sum, case when PCD.remittance_status = 'CONFIRM' then '已确认' else '未确认' end as remittance_status_n, PCD.remittance_status, PCD.CASH_DETAIL_ID, PCD.PRODUCT_ID, PCD.COLLECTION_ID, PCD.STRUCTURE_ID, PCD.TIMES, PCD.CASH_DATE, PCD.PLAN_CASH_PRINCIPAL, PCD.PLAN_CASH_INTEREST, PCD.CASH_PRINCIPAL, PCD.CASH_INTEREST, PCD.DESCRIPTION, PCD.ACTUAL_CASH_DATE, APS.PROJECT_STRUCTURE, ( SELECT SC.MEANING FROM SC WHERE SC.CODE_VALUE = APS.PROJECT_STRUCTURE AND SC.CODE = 'ABS.PRORITY_LEVEL' ) PROJECT_STRUCTURE_DESC, APS.PROJECT_GRADE, nvl(PCD.CASH_PRINCIPAL,0)+nvl(PCD.CASH_INTEREST,0) CASH_AMOUNT_SUM FROM CT_ABS_PRODUCT_CASH_DETAIL PCD LEFT JOIN CT_ABS_PRODUCT_STRUCTURE APS ON PCD.STRUCTURE_ID=APS.STRUCTURE_ID LEFT JOIN ct_abs_product cap ON cap.PRODUCT_ID = PCD.PRODUCT_ID LEFT JOIN ( SELECT pcfd.cash_detail_id, sum( nvl( pcfd.cash_amount_sum, 0 ) ) AS cash_amount_sum, sum( nvl( pcfd.cash_principal, 0 ) ) AS cash_principal_sum, sum( nvl( pcfd.cash_interest, 0 ) ) AS cash_interest_sum FROM ct_abs_product_cash_fb_detail pcfd GROUP BY pcfd.cash_detail_id ) as pcfd on pcfd.cash_detail_id = pcd.cash_detail_id WHERE 1=1
and PCD.COLLECTION_ID =#{collectionId}
and PCD.product_id = #{productId}
and PCD.cash_detail_id = #{cashDetailId}
ORDER BY PCD.TIMES
